alter table private.account_roles add column if not exists title text not null default '';
create table public.platform_events(id bigint generated always as identity primary key,actor_id uuid default auth.uid() references auth.users,id_target text,action text not null,details text not null default '',created_at timestamptz not null default now());
alter table public.platform_events enable row level security;
grant select on public.platform_events to authenticated;
create policy events_read on public.platform_events for select to authenticated using(private.has_permission('audit'));
create function private.log_platform_change() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.platform_events(actor_id,id_target,action,details) values(auth.uid(),coalesce(to_jsonb(new)->>'id',to_jsonb(new)->>'user_id',to_jsonb(new)->>'key'),tg_table_name||':'||tg_op,'Cambio administrativo registrado');return new;end $$;
revoke all on function private.log_platform_change() from public,anon,authenticated;
create function private.manage_team(person_email text,person_title text,person_role text,enabled boolean) returns void language plpgsql security definer set search_path='' as $$ declare target uuid;begin
if not private.has_permission('team') then raise exception 'Sin permiso para gestionar equipo';end if;
if person_role not in ('moderator','support','finance') or length(person_title)>120 then raise exception 'Rol o cargo inválido';end if;
select id into target from auth.users where lower(email)=lower(trim(person_email)) and email_confirmed_at is not null;
if target is null then raise exception 'La persona debe tener una cuenta y correo confirmado';end if;
if target=auth.uid() or exists(select 1 from private.account_roles where user_id=target and role='primary') then raise exception 'No se puede modificar al administrador principal';end if;
insert into private.account_roles(user_id,role,active,title) values(target,person_role,enabled,trim(person_title)) on conflict(user_id) do update set role=excluded.role,active=excluded.active,title=excluded.title;
insert into public.platform_events(actor_id,id_target,action,details) values(auth.uid(),target::text,'team:update',person_role||' active='||enabled::text);end $$;
revoke all on function private.manage_team(text,text,text,boolean) from public,anon;grant execute on function private.manage_team(text,text,text,boolean) to authenticated;
create function private.read_team() returns table(user_id uuid,name text,email text,title text,role text,active boolean) language sql stable security definer set search_path='' as $$ select r.user_id,p.name,p.email,r.title,r.role,r.active from private.account_roles r join public.profiles p on p.id=r.user_id where private.has_permission('team') $$;
revoke all on function private.read_team() from public,anon;grant execute on function private.read_team() to authenticated;
create function public.manage_team(person_email text,person_title text,person_role text,enabled boolean) returns void language sql security invoker set search_path='' as $$ select private.manage_team(person_email,person_title,person_role,enabled) $$;
create function public.read_team() returns table(user_id uuid,name text,email text,title text,role text,active boolean) language sql stable security invoker set search_path='' as $$ select * from private.read_team() $$;
revoke all on function public.manage_team(text,text,text,boolean),public.read_team() from public,anon;grant execute on function public.manage_team(text,text,text,boolean),public.read_team() to authenticated;
create table public.platform_ledger(id bigint generated always as identity primary key,actor_id uuid not null default auth.uid() references auth.users,entry_date date not null,kind text not null check(kind in ('income','expense','adjustment')),category text not null,amount_cents bigint not null check(amount_cents>0 and amount_cents<=100000000000),description text not null check(length(trim(description)) between 1 and 1000),reference text not null default '' check(length(reference)<=500),listing_id bigint references public.business_applications(id),activation_at timestamptz,request_key uuid not null unique,created_at timestamptz not null default now());
alter table public.platform_ledger enable row level security;
grant select on public.platform_ledger to authenticated;
grant insert(entry_date,kind,category,amount_cents,description,reference,listing_id,request_key) on public.platform_ledger to authenticated;
create policy ledger_read on public.platform_ledger for select to authenticated using(private.has_permission('finance'));
create policy ledger_insert on public.platform_ledger for insert to authenticated with check(private.has_permission('finance') and actor_id=auth.uid());
create function private.validate_ledger() returns trigger language plpgsql security definer set search_path='' as $$ begin
if not private.has_permission('finance') then raise exception 'Sin permiso de finanzas';end if;
perform pg_advisory_xact_lock(783201);
if new.entry_date>current_date then raise exception 'No se permiten movimientos futuros';end if;
if new.kind='adjustment' then
 if new.category<>'opening_balance' or exists(select 1 from public.platform_ledger) then raise exception 'Saldo inicial solo como primer movimiento';end if;
elsif new.kind='income' then
 if new.category not in ('membership','promotion','other') then raise exception 'Categoría de ingreso inválida';end if;
else if new.category not in ('hosting','translations','payment_fees','payroll','advertising','insurance','legal','refund','chargeback','other') then raise exception 'Categoría de gasto inválida';end if;end if;
if new.kind<>'adjustment' and exists(select 1 from public.platform_ledger where kind='adjustment' and entry_date>new.entry_date) then raise exception 'La fecha no puede ser anterior al saldo inicial';end if;
if new.category='membership' and new.listing_id is null then raise exception 'Selecciona un negocio para la membresía';end if;
if new.listing_id is not null then select activated_at into new.activation_at from public.business_applications where id=new.listing_id and status='approved';if not found then raise exception 'El negocio debe estar aprobado';end if;end if;
return new;end $$;
revoke all on function private.validate_ledger() from public,anon,authenticated;
create trigger validate_ledger before insert on public.platform_ledger for each row execute function private.validate_ledger();
create trigger audit_ledger after insert on public.platform_ledger for each row execute function private.log_platform_change();
create table public.support_tickets(id bigint generated always as identity primary key,owner_id uuid not null default auth.uid() references auth.users,subject text not null check(length(trim(subject)) between 1 and 160),message text not null check(length(trim(message)) between 1 and 5000),status text not null default 'open' check(status in ('open','in_progress','closed')),created_at timestamptz not null default now());
alter table public.support_tickets enable row level security;
grant select on public.support_tickets to authenticated;grant insert(subject,message) on public.support_tickets to authenticated;grant update(status) on public.support_tickets to authenticated;
create policy tickets_read on public.support_tickets for select to authenticated using(owner_id=auth.uid() or private.has_permission('users'));
create policy tickets_create on public.support_tickets for insert to authenticated with check(owner_id=auth.uid() and status='open' and exists(select 1 from public.profiles where id=auth.uid() and verified));
create policy tickets_update on public.support_tickets for update to authenticated using(private.has_permission('users')) with check(private.has_permission('users'));
create table public.support_replies(id bigint generated always as identity primary key,ticket_id bigint not null references public.support_tickets(id),author_id uuid not null default auth.uid() references auth.users,message text not null check(length(trim(message)) between 1 and 5000),created_at timestamptz not null default now());
alter table public.support_replies enable row level security;
grant select on public.support_replies to authenticated;grant insert(ticket_id,message) on public.support_replies to authenticated;
create policy reply_read on public.support_replies for select to authenticated using(exists(select 1 from public.support_tickets t where t.id=ticket_id and (t.owner_id=auth.uid() or private.has_permission('users'))));
create policy reply_create on public.support_replies for insert to authenticated with check(author_id=auth.uid() and exists(select 1 from public.support_tickets t where t.id=ticket_id and t.status<>'closed' and (t.owner_id=auth.uid() or private.has_permission('users'))));
create trigger audit_ticket after update on public.support_tickets for each row execute function private.log_platform_change();
create table public.promotions(id bigint generated always as identity primary key,listing_id bigint not null references public.business_applications(id),title text not null check(length(trim(title)) between 1 and 160),description text not null check(length(description)<=2000),image_url text not null default '' check(image_url='' or image_url ~ '^https://'),language text not null default 'es' check(length(language) between 2 and 30),starts_at timestamptz not null,ends_at timestamptz not null,status text not null default 'draft' check(status in ('draft','published','paused')),created_at timestamptz not null default now(),check(ends_at>starts_at));
alter table public.promotions enable row level security;
grant select on public.promotions to anon,authenticated;grant insert(listing_id,title,description,image_url,language,starts_at,ends_at,status),update(title,description,image_url,language,starts_at,ends_at,status) on public.promotions to authenticated;
create policy promo_read on public.promotions for select to authenticated using((status='published' and now()>=starts_at and now()<ends_at and exists(select 1 from public.business_directory d where d.id=listing_id)) or private.has_permission('listings'));
create policy promo_insert on public.promotions for insert to authenticated with check(private.has_permission('listings') and exists(select 1 from public.business_directory d where d.id=listing_id));
create policy promo_update on public.promotions for update to authenticated using(private.has_permission('listings')) with check(private.has_permission('listings'));
create trigger audit_promotions after insert or update on public.promotions for each row execute function private.log_platform_change();
create table public.business_verifications(id bigint generated always as identity primary key,listing_id bigint not null references public.business_applications(id),kind text not null check(kind in ('registration','license','insurance')),reference text not null default '' check(length(reference)<=300),source_url text not null default '' check(source_url='' or source_url ~ '^https://'),checked_on date not null default current_date,expires_on date,note text not null default '' check(length(note)<=2000),created_at timestamptz not null default now());
alter table public.business_verifications enable row level security;
grant select on public.business_verifications to authenticated;grant insert(listing_id,kind,reference,source_url,checked_on,expires_on,note) on public.business_verifications to authenticated;
create policy verification_read on public.business_verifications for select to authenticated using(private.has_permission('verification'));
create policy verification_insert on public.business_verifications for insert to authenticated with check(private.has_permission('verification'));
create trigger audit_verifications after insert on public.business_verifications for each row execute function private.log_platform_change();
create table public.platform_settings(key text primary key check(key in ('support_email','platform_notice')),value text not null check(length(value)<=2000));
alter table public.platform_settings enable row level security;grant select on public.platform_settings to anon,authenticated;grant insert,update on public.platform_settings to authenticated;
create policy settings_read on public.platform_settings for select to anon,authenticated using(true);
create policy settings_insert on public.platform_settings for insert to authenticated with check(private.has_permission('team'));
create policy settings_update on public.platform_settings for update to authenticated using(private.has_permission('team')) with check(private.has_permission('team'));
create trigger audit_settings after insert or update on public.platform_settings for each row execute function private.log_platform_change();
create table public.service_catalog(id bigint generated always as identity primary key,family text not null check(length(trim(family)) between 1 and 120),service text not null check(length(trim(service)) between 1 and 160),active boolean not null default true,unique(family,service));
create unique index service_catalog_normalized on public.service_catalog(lower(trim(family)),lower(trim(service)));
alter table public.service_catalog enable row level security;grant select on public.service_catalog to anon,authenticated;grant insert(family,service,active),update(active) on public.service_catalog to authenticated;
create policy catalog_read on public.service_catalog for select to authenticated using(active or private.has_permission('listings'));
create policy catalog_public on public.service_catalog for select to anon using(active);
create policy catalog_insert on public.service_catalog for insert to authenticated with check(private.has_permission('listings'));
create policy catalog_update on public.service_catalog for update to authenticated using(private.has_permission('listings')) with check(private.has_permission('listings'));
create trigger audit_catalog after insert or update on public.service_catalog for each row execute function private.log_platform_change();
create index support_owner on public.support_tickets(owner_id);create index replies_ticket on public.support_replies(ticket_id);create index promos_listing on public.promotions(listing_id);create index ledger_listing on public.platform_ledger(listing_id);create index verifications_listing on public.business_verifications(listing_id);

create policy promo_public on public.promotions for select to anon using(status='published' and now()>=starts_at and now()<ends_at and exists(select 1 from public.business_directory d where d.id=listing_id));
